import React, {type ReactNode, useContext} from 'react';
import {ReactContextError} from '@docusaurus/theme-common/internal';
import type {PropVersionMetadata} from '@docusaurus/plugin-content-docs';
import type {
  GlobalPluginData,
  GlobalVersion,
} from '@docusaurus/plugin-content-docs/client';
import {DocsDocumentSnapshot, DocsDraftIndex} from './doc';

const Context = React.createContext<PropVersionMetadata | null>(null);

/**
 * Provide the current version's metadata to your children.
 */
export function DocsVersionProvider({
  children,
  version,
}: {
  children: ReactNode;
  version: PropVersionMetadata | null;
}): JSX.Element {
  return <Context.Provider value={version}>{children}</Context.Provider>;
}

/**
 * Gets the version metadata of the current doc page.
 */
export function useDocsVersion(): PropVersionMetadata {
  const version = useContext(Context);
  if (version === null) {
    throw new ReactContextError('DocsVersionProvider');
  }
  return version;
}

export class DocsPluginSnapshot {
  constructor(private readonly data: GlobalPluginData) {}

  getPath(): string {
    return this.data.path;
  }

  getVersionSnapshots(): DocsVersionSnapshot[] {
    return this.data.versions.map(
      (version) => new DocsVersionSnapshot(version),
    );
  }
}

export class DocsVersionSnapshot {
  constructor(private readonly version: GlobalVersion) {}

  getName(): string {
    return this.version.name;
  }

  getIsLast(): boolean {
    return this.version.isLast;
  }

  getPath(): string {
    return this.version.path;
  }

  getMainDocId(): string {
    return this.version.mainDocId;
  }

  getDocuments(): DocsDocumentSnapshot[] {
    return (this.version.docs ?? []).map(
      (doc) => new DocsDocumentSnapshot(doc, this.version.sidebars),
    );
  }

  getDrafts(): DocsDraftIndex {
    return new DocsDraftIndex(this.version.draftIds ?? []);
  }

  unwrap(): GlobalVersion {
    return this.version;
  }
}

