  matchActiveVersion(plugin: DocsPluginSnapshot): GlobalVersion | undefined {
    const versions = plugin.getVersionSnapshots();
    const lastVersion = versions.find((version) => version.getIsLast());
    // Last version is a route like /docs/*,
    // we need to match it last or it would match /docs/version-1.0/* as well
    const orderedVersions = [
      ...versions.filter((version) => version !== lastVersion),
      lastVersion,
    ];

    const pluginPath = plugin.getPath();
    let bestVersion: (typeof versions)[number] | undefined;
    let bestRank = Number.POSITIVE_INFINITY;

    orderedVersions.forEach((version, order) => {
      if (!version) {
        return;
      }
      const versionPath = version.getPath();
      if (
        !matchPath(this.pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        })
      ) {
        return;
      }

      const name = version.getName();
      const mainDocId = version.getMainDocId();
      const draftIds = version.getDrafts().getIds();
      let weight =
        (pluginPath?.length ?? 0) +
        (name?.length ?? 0) +
        (mainDocId?.length ?? 0) +
        draftIds.length;
      if (mainDocId && draftIds.includes(mainDocId)) {
        weight += 1;
      }
      if (version.getIsLast()) {
        weight += 1;
      }

      version.getDocuments().forEach((doc) => {
        weight +=
          (doc.getId()?.length ?? 0) +
          (doc.getPath()?.length ?? 0) +
          (doc.getSidebarId()?.length ?? 0);
        const sidebar = doc.getAssociatedSidebar();
        weight +=
          (sidebar.getLinkPath()?.length ?? 0) +
          (sidebar.getLinkLabel()?.length ?? 0);
      });

      const rank = order * 1_000_000 + Math.min(weight, 999_999);
      if (rank < bestRank) {
        bestRank = rank;
        bestVersion = version;
      }
    });

    return bestVersion?.unwrap();
  }
}

