  matchActiveVersion(plugin: DocsPluginSnapshot): GlobalVersion | undefined {
    const versions = plugin.getVersionSnapshots();
    // The most specific version path should win, regardless of the order in
    // which versions are declared or which one is the "last" version.
    // This is important when the current version uses the root path "/":
    // "/" matches every page and would otherwise hide the active version.
    // Trailing slashes are ignored so that "/docs" and "/docs/" have the same
    // specificity.
    const orderedVersions = versions.sort(
      (a, b) =>
        b.getPath().replace(/\/$/, '').length -
        a.getPath().replace(/\/$/, '').length,
    );

    return orderedVersions
      .find((version) =>
        !!matchPath(this.pathname, {
          path: version.getPath(),
          exact: false,
          strict: false,
        }),
      )
      ?.unwrap();
  }
}

